<?php
declare(strict_types=1);require_once __DIR__.'/../includes/functions.php';require_admin();if($_SERVER['REQUEST_METHOD']!=='POST')redirect('admin/index.php');verify_csrf();$id=(int)($_POST['id']??0);$title=trim($_POST['title']??'');$raw=trim($_POST['slug']??'');$excerpt=trim($_POST['excerpt']??'');$image=trim($_POST['image_url']??'');$uploadedImage=handle_image_upload($_FILES['image_file']??[]);if($uploadedImage!==null){$image=$uploadedImage;}$content=trim($_POST['content']??'');$cat=($_POST['category_id']??'')!==''?(int)$_POST['category_id']:null;$status=in_array($_POST['status']??'',['draft','published'],true)?$_POST['status']:'draft';$featured=isset($_POST['is_featured'])?1:0;$published=trim($_POST['published_at']??'');$published=$published?date('Y-m-d H:i:s',strtotime($published)):date('Y-m-d H:i:s');if($title===''||$content===''){http_response_code(422);exit('Заголовок и текст обязательны.');}$slug=unique_slug(slugify($raw!==''?$raw:$title),$id?:null);$content=strip_tags($content,'<p><br><strong><b><em><i><u><h2><h3><blockquote><ul><ol><li><a>');$pdo=db();$pdo->beginTransaction();try{if($featured)$pdo->exec('UPDATE posts SET is_featured=0');if($id){$s=$pdo->prepare("UPDATE posts SET title=?,slug=?,excerpt=?,content=?,image_url=?,category_id=?,status=?,is_featured=?,published_at=?,updated_at=NOW() WHERE id=?");$s->execute([$title,$slug,$excerpt,$content,$image?:null,$cat,$status,$featured,$published,$id]);}else{$s=$pdo->prepare("INSERT INTO posts(title,slug,excerpt,content,image_url,category_id,author_id,status,is_featured,published_at) VALUES(?,?,?,?,?,?,?,?,?,?)");$s->execute([$title,$slug,$excerpt,$content,$image?:null,$cat,(int)$_SESSION['user_id'],$status,$featured,$published]);}$pdo->commit();flash('success','Публикация сохранена.');}catch(Throwable $e){$pdo->rollBack();throw $e;}redirect('admin/index.php');
